\u0438 = 1 \\u0443\\u0434\\u0430\\u0440/2 \\u0448\\u0430\\u0433\\u0430, \\u0443\\u0440\\u043e\\u043d = 15 HP).\\n  - \\u0410\\u043b\\u0433\\u043e\\u0440\\u0438\\u0442\\u043c \\u043f\\u0438\\u0440\\u0430\\u0442\\u043e\\u0432: \\u0430\\u0433\\u0440\\u0435\\u0441\\u0441\\u0438\\u0432\\u043d\\u043e\\u0435 \\u043f\\u0440\\u0435\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 (A* pathfinding \\u043a \\u0430\\u0433\\u0435\\u043d\\u0442\\u0443 \\u0441 \\u0432\\u0435\\u043a\\u0442\\u043e\\u0440\\u043e\\u043c \\u0443\\u043f\\u0440\\u0435\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f).\\n  - **\\u041f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c:** \\u0415\\u0441\\u043b\\u0438 \\u043f\\u0435\\u0440\\u0432\\u0430\\u044f \\u0432\\u043e\\u043b\\u043d\\u0430 \\u0443\\u043d\\u0438\\u0447\\u0442\\u043e\\u0436\\u0435\\u043d\\u0430, \\u0441\\u043b\\u0435\\u0434\\u0443\\u044e\\u0449\\u0430\\u044f \\u0432\\u043e\\u043b\\u043d\\u0430 \\u0441\\u043f\\u0430\\u0432\\u043d\\u0438\\u0442\\u0441\\u044f \\u043a\\u0430\\u0436\\u0434\\u044b\\u0435 $\\\\Delta t_{\\\\text{wave}} = 150$ \\u0448\\u0430\\u0433\\u043e\\u0432 \\u0441 \\u043d\\u0430\\u0440\\u0430\\u0441\\u0442\\u0430\\u043d\\u0438\\u0435\\u043c \\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 ($+1$ \\u044e\\u043d\\u0438\\u0442 \\u0437\\u0430 \\u0432\\u043e\\u043b\\u043d\\u0443).\\n- **\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u0435 (Ablation / Trigger Disabled):**\\n  \\u041f\\u0440\\u0438 $S_t \\\\ge S_{\\\\text{thresh}}$ \\u0441\\u0447\\u0435\\u0442 \\u043f\\u0440\\u043e\\u0434\\u043e\\u043b\\u0436\\u0430\\u0435\\u0442 \\u0440\\u0430\\u0441\\u0442\\u0438, \\u043f\\u0438\\u0440\\u0430\\u0442\\u044b **\\u043d\\u0435 \\u0441\\u043f\\u0430\\u0432\\u043d\\u044f\\u0442\\u0441\\u044f**, \\u0441\\u043f\\u0430\\u0432\\u043d\\u044f\\u0442\\u0441\\u044f \\u0442\\u043e\\u043b\\u044c\\