3\\u043e\\u0432 \\u0441\\u0440\\u0435\\u0434\\u044b (\\u043c\\u0430\\u043a\\u0440\\u043e-\\u0448\\u0430\\u0433).\\n  - \\u0413\\u0435\\u043d\\u0435\\u0440\\u0438\\u0440\\u0443\\u0435\\u0442 \\u043b\\u0430\\u0442\\u0435\\u043d\\u0442\\u043d\\u044b\\u0439 \\u0432\\u0435\\u043a\\u0442\\u043e\\u0440 \\u0446\\u0435\\u043b\\u0438 $g_k \\\\in \\\\mathbb{R}^8$ (\\u0438\\u043b\\u0438 \\u043a\\u0430\\u0442\\u0435\\u0433\\u043e\\u0440\\u0438\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0432\\u044b\\u0431\\u043e\\u0440 \\u043e\\u0434\\u043d\\u043e\\u0433\\u043e \\u0438\\u0437 4 \\u0434\\u0438\\u0441\\u043a\\u0440\\u0435\\u0442\\u043d\\u044b\\u0445 \\u0440\\u0435\\u0436\\u0438\\u043c\\u043e\\u0432: *Resource Gathering*, *Base Fortification*, *Direct Combat*, *Evasive Kiting*).\\n  - \\u041e\\u0431\\u0443\\u0447\\u0430\\u0435\\u0442\\u0441\\u044f \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0434\\u0438\\u0441\\u043a\\u043e\\u043d\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0443\\u044e \\u0441\\u0443\\u043c\\u043c\\u0443 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0438\\u0445 \\u043d\\u0430\\u0433\\u0440\\u0430\\u0434 \\u0441\\u0440\\u0435\\u0434\\u044b \\u0441 \\u0448\\u0430\\u0433\\u043e\\u043c $c$: $\\\\sum_{i=0}^{\\\\infty} \\\\gamma_{\\\\text{hi}}^i R_{t + i \\\\cdot c}$.\\n- **Worker (\\u041d\\u0438\\u0437\\u043a\\u043e\\u0443\\u0440\\u043e\\u0432\\u043d\\u0435\\u0432\\u0430\\u044f \\u043f\\u043e\\u043b\\u0438\\u0442\\u0438\\u043a\\u0430 $\\\\pi_{\\\\text{lo}}$):**\\n  - \\u041f\\u0440\\u0438\\u043d\\u0438\\u043c\\u0430\\u0435\\u0442 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0435\\u0435 \\u043d\\u0430\\u0431\\u043b\\u044e\\u0434\\u0435\\u043d\\u0438\\u0435 $o_t$ \\u0438 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0443\\u044e \\u0446\\u0435\\u043b\\u044c $g_k$.\\n  - \\u0412\\u044b\\u0434\\u0430\\u0435\\u0442 \\u043f\\u0440\\u0438\\u043c\\u0438\\u0442\\u0438\\u0432\\u043d\\u043e\\u0435 \\u0434\\u0435\\u0439\\u0441\\u0442\\u0432\\u0438\\u0435 $a_t \\\\in \\\\mathcal{A}$ \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u0448\\u0430\\u0433 \\u0441\\u0440\\u0435\\u0434\\u044b.\\n  - \\u041e\\u0431\\u0443\\u0447\\u0430\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e \\u0444\\u0443\\u043d\\u043a\\u0446\\u0438\\u0438 \\u0432\\u043d\\u0443\\u0442\\u0440\\u0435\\u043d\\u043d\\u0435\\u0433\\u043e \\u0432\\u043e\\u0437\\u043d\\u0430\\u0433\\u0440\\u0430\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f (intrinsic reward) \\u043a\\u043e\\u0441\\u0438\\u043d\\u0443\\u0441\\u043d\\u043e\\u0433\\u043e \\u0441\\u0445\\u043e\\u0434\\u0441\\u0442\\u0432\\u0430 \\u0438\\u0437\\u043c\\u0435\\u043d\\u0435\\u043d\\u0438\\u0439 \\u043b\\u0430\\u0442\\u0435\\u043d\\u0442\\u043d\\u044b\\u0445 \\u044d\\u043c\\u0431\\u0435\\u0434\\u0434\\u0438\\u043d\\u0433\\u043e\\u0432 \\u0438\\u043b\\u0438 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0444\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u043c\\u0430\\u043a\\u0440\\u043e-\\u0437\\u0430\\u0434\\u0430\\u0447\\u0438: $r^{\\\\text{in}}_t = \\\\cos(e(s_{t+1}) - e(s_t), g_k)$.\\n- **\\u0411\\u0430\\u0437\\u043e\\u0432\\u044b\\u0439 \\u0430\\u043b\\u0433\\u043e\\u0440\\u0438\\u0442\\u043c:** FeUdal Networks (FuN) \\u0438\\u043b\\u0438 HiPPO/Option-Critic.\\n\\n### 3.2. \\u041d\\u0435\\u0438\\u0435\\u0440\\u0430\\u0440\\u0445\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043f\\u043b\\u043e\\u0441\\u043a\\u0438\\u0439 \\u0430\\u0433\\u0435\\u043d\\u0442 (Flat Baseline: PPO)\\n- **\\u0410\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u0430:** \\u041c\\u043e\\u043d\\u043e\\u043b\\u0438\\u0442\\u043d\\u0430\\u044f \\u0441\\u0432\\u0435\\u0440\\u0442\\u043e\\u0447\\u043d\\u0430\\u044f/\\u043f\\u043e\\u043b\\u043d\\u043e\\u0441\\u0432\\u044f\\u0437\\u043d\\u0430\\u044f \\u0441\\u0435\\u0442\\u044c (CNN-LSTM backbone + Actor-Critic heads).\\n- **\\u0412\\u0445\\u043e\\u0434:** \\u0422\\u0435\\u043a\\u0443\\u0449\\u0435\\u0435 \\u043d\\u0430\\u0431\\u043b\\u044e\\u0434\\u0435\\u043d\\u0438\\u0435 $o_t$ \\u0438 \\u043f\\u0440\\u0435\\u0434\\u044b\\u0434\\u0443\\u0449\\u0435\\u0435 \\u0441\\u043a\\u0440\\u044b\\u0442\\u043e\\u0435 \\u0441\\u043e\\u0441\\u0442\\u043e\\u044f\\u043d\\u0438\\u0435 LSTM $h_{t-1}$.\\n- **\\u0412\\u044b\\u0445\\u043e\\u0434:** \\u0420\\u0430\\u0441\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0432\\u0435\\u0440\\u043e\\u044f\\u0442\\u043d\\u043e\\u0441\\u0442\\u0435\\u0439 \\u043d\\u0430\\u0434 \\u043f\\u0440\\u0438\\u043c\\u0438\\u0442\\u0438\\u0432\\u043d\\u044b\\u043c\\u0438 \\u0434\\u0435\\u0439\\u0441\\u0442\\u0432\\u0438\\u044f\\u043c\\u0438 $a_t \\\\in \\\\mathcal{A}$ \\u0438 \\u043e\\u0446\\u0435\\u043d\\u043a\\u0430 \\u0446\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 $V(s_t)$.\\n- **\\u0411\\u0430\\u0437\\u043e\\u0432\\u044b\\u0439 \\u0430\\u043b\\u0433\\u043e\\u0440\\u0438\\u0442\\u043c:** Proximal Policy Optimization (PPO) \\u0441 \\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u044b\\u043c \\u043e\\u043a\\u043d\\u043e\\u043c \\u0440\\u0435\\u043a\\u0443\\u0440\\u0440\\u0435\\u043d\\u0442\\u043d\\u043e\\u0439 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438, \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0442\\u043e\\u0440\\u043e\\u043c Adam \\u0438 \\u0442\\u0435\\u043c \\u0436\\u0435 \\u0447\\u0438\\u0441\\u043b\\u043e\\u043c \\u0441\\u043a\\u0440\\u044b\\u0442\\u044b\\u0445 \\u043d\\u0435\\u0439\\u0440\\u043e\\u043d\\u043e\\u0432, \\u0447\\u0442\\u043e \\u0441\\u0443\\u043c\\u043c\\u0430\\u0440\\u043d\\u043e \\u0443 Manager + Worker.\\n\\n---\\n\\n## 4. \\u0421\\u0445\\u0435\\u043c\\u0430 \\u0444\\u0430\\u043a\\u0442\\u043e\\u0440\\u043d\\u043e\\u0433\\u043e \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430 (2 \\u00d7 2 \\u00d7 2)\\n\\n\\u042d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442 \\u0441\\u0442\\u0440\\u043e\\u0438\\u0442\\u0441\\u044f \\u043f\\u043e \\u043c\\u043d\\u043e\\u0433\\u043e\\u0444\\u0430\\u043a\\u0442\\u043e\\u0440\\u043d\\u043e\\u0439 \\u0441\\u0445\\u0435\\u043c\\u0435 \\u0441 \\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435\\u043c \\u043d\\u0430 \\u0440\\u0435\\u0436\\u0438\\u043c\\u044b \\u0430\\u0434\\u0430\\u043f\\u0442\\u0430\\u0446\\u0438\\u0438:\\n\\n| \\u0424\\u0430\\u043a\\u0442\\u043e\\u0440 | \\u0423\\u0440\\u043e\\u0432\\u043d\\u0438 | \\u041e\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u0435 |\\n| :--- | :--- | :--- |\\n| **\\u0424\\u0430\\u043a\\u0442\\u043e\\u0440 1: \\u0410\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u0430 ($\\\\mathcal{A}$)** | 1. `HRL` (Manager-Worker)<br>2. `Flat` (PPO) | \\u0421\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u043d\\u043e\\u0433\\u043e \\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u044f \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 \\u043c\\u043e\\u043d\\u043e\\u043b\\u0438\\u0442\\u043d\\u043e\\u0439 \\u043f\\u043e\\u043b\\u0438\\u0442\\u0438\\u043a\\u0438 |\\n| **\\u0424\\u0430\\u043a\\u0442\\u043e\\u0440 2: \\u0422\\u0440\\u0438\\u0433\\u0433\\u0435\\u0440 \\u043f\\u0438\\u0440\\u0430\\u0442\\u043e\\u0432 ($\\\\mathcal{T}$)** | 1. `Trigger ON` (\\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u043a\\u0430 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u0430)<br>2. `Trigger OFF` (\\u0430\\u0431\\u043b\\u0430\\u0446\\u0438\\u044f \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u043a\\u0438) | \\u041f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430 \\u0438\\u0437\\u043e\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0430 \\u0432\\u0442\\u043e\\u0440\\u0436\\u0435\\u043d\\u0438\\u044f |\\n| **\\u0424\\u0430\\u043a\\u0442\\u043e\\u0440 3: \\u0420\\u0435\\u0436\\u0438\\u043c \\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f ($\\\\mathcal{M}$)** | 1. `Standard/In-Distribution`<br>2. `Zero-Shot/OOD Shift` | \\u041e\\u0446\\u0435\\u043d\\u043a\\u0430 \\u0430\\u0434\\u0430\\u043f\\u0442\\u0438\\u0432\\u043d\\u043e\\u0441\\u0442\\u0438 \\u043f\\u0440\\u0438 \\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u043e\\u0439 vs \\u043d\\u0435\\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u043e\\u0439 \\u0443\\u0433\\u0440\\u043e\\u0437\\u0435 |\\n\\n### \\u0420\\u0435\\u0436\\u0438\\u043c\\u044b \\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f \\u0438 \\u0442\\u0435\\u0441\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f:\\n1. **\\u0421\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439 A (In-Distribution Evaluation):**\\n   - \\u0410\\u0433\\u0435\\u043d\\u0442\\u044b (HRL \\u0438 Flat) \\u043e\\u0431\\u0443\\u0447\\u0430\\u044e\\u0442\\u0441\\u044f \\u0432 \\u0441\\u0440\\u0435\\u0434\\u0435 \\u0441 \\u0430\\u043a\\u0442\\u0438\\u0432\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u043c \\u0442\\u0440\\u0438\\u0433\\u0433\\u0435\\u0440\\u043e\\u043c \\u043f\\u0438\\u0440\\u0430\\u0442\\u043e\\u0432 \\u043d\\u0430 \\u043f\\u0440\\u043e\\u0442\\u044f\\u0436\\u0435\\u043d\\u0438\\u0438 $5 \\\\times 10^7$ \\u0448\\u0430\\u0433\\u043e\\u0432.\\n   - \\u0422\\u0435\\u0441\\u0442\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u0432 \\u0434\\u0432\\u0443\\u0445 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f\\u0445: `Trigger ON` vs `Trigger OFF`.\\n2. **\\u0421\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439 B (Zero-Shot Robustness / Out-of-Distribution Ablation):**\\n   - \\u0410\\u0433\\u0435\\u043d\\u0442\\u044b \\u043e\\u0431\\u0443\\u0447\\u0430\\u044e\\u0442\\u0441\\u044f \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u0432 \\u043c\\u0438\\u0440\\u043d\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u0435 (`Trigger OFF`, \\u043f\\u0438\\u0440\\u0430\\u0442\\u044b \\u043d\\u0438\\u043