\\u044d\\u043f\\u0438\\u0437\\u043e\\u0434\\u0430 \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0430 $T_{\\\\max} = 5000$ \\u0448\\u0430\\u0433\\u0430\\u043c\\u0438. \\u0415\\u0441\\u043b\\u0438 \\u0430\\u0433\\u0435\\u043d\\u0442 \\u0436\\u0438\\u0432 \\u043a \\u0448\\u0430\\u0433\\u0443 $T_{\\\\max}$, \\u0438\\u0441\\u0445\\u043e\\u0434 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u0446\\u0435\\u043d\\u0437\\u0443\\u0440\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0435 \\u043d\\u0430\\u0431\\u043b\\u044e\\u0434\\u0435\\u043d\\u0438\\u0435 ($C_i = 0$, \\u00ab\\u043d\\u0435 \\u043f\\u043e\\u0433\\u0438\\u0431\\u00bb).\\n3. **\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0432\\u043c\\u0435\\u0448\\u0438\\u0432\\u0430\\u044e\\u0449\\u0438\\u0445\\u0441\\u044f \\u0444\\u0430\\u043a\\u0442\\u043e\\u0440\\u043e\\u0432 (Confounders):**\\n   - *\\u0424\\u0430\\u043a\\u0442\\u043e\\u0440 \\u0442\\u0435\\u043c\\u043f\\u0430 \\u043d\\u0430\\u0431\\u043e\\u0440\\u0430 \\u043e\\u0447\\u043a\\u043e\\u0432:* \\u0420\\u0430\\u0437\\u043d\\u044b\\u0435 \\u0430\\u0433\\u0435\\u043d\\u0442\\u044b \\u043c\\u043e\\u0433\\u0443\\u0442 \\u0434\\u043e\\u0441\\u0442\\u0438\\u0433\\u0430\\u0442\\u044c $S_{\\\\text{thresh}}$ \\u0432 \\u0440\\u0430\\u0437\\u043d\\u043e\\u0435 \\u0432\\u0440\\u0435\\u043c\\u044f $t_{\\\\text{trig}}$. \\u041f\\u043e\\u044d\\u0442\\u043e\\u043c\\u0443 \\u043a\\u043b\\u044e\\u0447\\u0435\\u0432\\u043e\\u0439 \\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u043e\\u0439 \\u0448\\u043a\\u0430\\u043b\\u043e\\u0439 \\u0432\\u044b\\u0436\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f \\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e\\u0441\\u0442-\\u0442\\u0440\\u0438\\u0433\\u0433\\u0435\\u0440\\u043d\\u043e\\u0435 \\u0432\\u0440\\u0435\\u043c\\u044f: $\\\\tau_i = T_{\\\\text{death}, i} - t_{\\\\text{trig}, i}$.\\n   - *\\u0418\\u0441\\u043a\\u0